#-----------------------------------------------------------------------------
# TBS Buried Sea island missions - Johnny the Black Crow
# npc_types id 423144 (Johnny_the_Black_Crow)
# Auto-generated by tbs_content/gen_jonas_givers.py from scraped Allakhazam dialogs.
# Offers tasks in order; each task is non-repeatable.
#-----------------------------------------------------------------------------

my %chains = (
    620022 =>
        [
         "Har har.  That's more like it, $name.  I'm liking you already.  Now, unless you've got a map of " . quest::saylink("Redfeather Isle") . " tattooed to your backside, shove off, swabby.  Johnny is a busy man.",
         ["What chests?", "Long story, that, involving bloodshed, betrayal, and burning sails.  The long and short of it is that a merchant vessel was downed just off the coast of Redfeather Isle and I've got the impression that the booty washed ashore, among the bird people.  If you somehow stumble upon the goods I've a mind to award you for the " . quest::saylink("effort") . "."],
         ["Effort?", "Alright, if you insist, $name.  Head out to Redfeather Isle.  Look on the coast for boxes washed up on shore, or perhaps just under the water.  The merchant vessel's goods will be of no use to you, but they're of particular importance to some associates of mine."],
        ],
    620023 =>
        [
         "Har har.  That's more like it, $name.  I'm liking you already.  Now, unless you've got a map of " . quest::saylink("Redfeather Isle") . " tattooed to your backside, shove off, swabby.  Johnny is a busy man.",
         ["What landmarks?", "My map's no good without the landmarks on the island pinpointed.  I could see them from the waters but just as ghostly silhouettes.  Would need to get much " . quest::saylink("closer") . " to pinpoint their exact locations."],
         ["I", "Scout out the island and get back to me with the information I need.  The bird people aren't quite so fearsome as the Black Crow, but they'll give you a fight if you get too close."],
        ],
);

my @mytasks = (620022, 620023);

sub EVENT_SAY {
  # first task of mine the player has not completed
  my $next = -1;
  for my $i (0 .. $#mytasks) {
    if (!quest::istaskcompleted($mytasks[$i])) { $next = $i; last; }
  }
  if ($next < 0) {
    if ($text=~/hail/i) {
      quest::say("You have done more than enough for me, $name. The sea itself owes you a debt now.");
    }
    return;
  }
  my $tid = $mytasks[$next];
  if (quest::istaskactive($tid)) {
    if ($text=~/hail/i) {
      quest::say("Get a move on, $name! The work will not do itself.");
    }
    return;
  }
  my $chain = $chains{$tid};
  return if !$chain;
  my $hail = $chain->[0];
  my @hops = @{$chain}[1 .. $#$chain];

  if ($text=~/hail/i) {
    quest::say($hail);
    return;
  }

  # find which hop the player triggered
  my $hit = -1;
  for my $i (0 .. $#hops) {
    if ($text=~/\Q$hops[$i][0]\E/i) { $hit = $i; last; }
  }
  return if $hit < 0;
  quest::say($hops[$hit][1]);
  # the final hop hands out the work
  if ($hit == $#hops) {
    quest::assigntask($tid);
  }
}

sub EVENT_ITEM {
  # deliver steps of the island tasks are task-deliveries;
  # anything else handed to us is returned.
  plugin::return_items(\%itemcount);
}
